/* aae_romload.h — load an AAE game's romset from the .zip, instead of embedding it.
 *
 * THE MAME MODEL: the game does not carry the ROM inside; it reads it from
 * roms/<GAME>.ZIP on the card (or from the file system, on host and in the simulator). The
 * difference with a single-file loader is that an arcade romset brings one file per chip
 * and each one goes to a different address, so they have to be asked for by name.
 *
 * THE NAME IS THE EXACT ZIP MEMBER NAME, and the table is generated by a tool with the zip
 * in front of it. There is no fuzzy matching here: what AAE calls "035127.02" may be in the
 * zip as "035127-02.np3", and resolving that means looking inside the zip. Doing it on the
 * cartridge would turn "a file is missing" into "the game behaves oddly".
 */
#ifndef AAE_ROMLOAD_H
#define AAE_ROMLOAD_H

#define AAE_ROM_PLAIN 0   /* consecutive bytes at GI[region] + addr                */
#define AAE_ROM_EVEN  1   /* 16-bit interleave: even bytes (addr + j*2)            */
#define AAE_ROM_ODD   2   /* 16-bit interleave: odd bytes  (addr + j*2 + 1)        */

/* The stage: an intermediate for what cannot be decompressed straight onto GI[] — the
 * interleave (strided destination) and ROM_CONTINUE (a SLICE of the file is copied, so the
 * whole file is needed first). 0 by default; a game that needs one raises it in its
 * Makefile, and the romtable generator says how much. */
#ifndef AAE_ROM_STAGE
#define AAE_ROM_STAGE 0u
#endif

typedef struct {
    const char  *file;     /* exact name in the zip; NULL = repeat the previous one */
    unsigned int addr;     /* destination inside the region */
    unsigned int size;     /* how much is copied */
    unsigned int src_off;  /* from which byte of the FILE (ROM_CONTINUE); 0 = the start */
    unsigned char region;  /* 0 = GI[CPU0], 1 = GI[CPU1] */
    unsigned char mode;    /* AAE_ROM_PLAIN / _EVEN / _ODD */
} aae_rom_op;

/* 0 = everything loaded. Non-zero = the index of the operation that failed, plus 1, so the
 * game can say ON SCREEN which one was missing: an incomplete romset and an absent romset
 * are not fixed the same way, and without telling them apart both are a black screen. */
int aae_rom_load(const aae_rom_op *ops, int n);

/* The same load against an arbitrary set of region pointers. This is what the hand-written
 * ports use, since they have their own arrays rather than AAE's GI[]. */
int aae_rom_load_bases(const aae_rom_op *ops, int n, unsigned char *const *bases);

/* Why the last load failed: the code from romzip.h (RA_ROMZIP_*), or 0. */
extern int aae_rom_last_error;

/* Paints the failure as text, with the path it tried. It is called in a loop when the load
 * fails, INSTEAD of emulating over zeros — which draws nothing and is indistinguishable
 * from a hang. It carries its own tiny vector font: AAE games do not have one. */
void aae_rom_error_screen(int code);

/* One centred line of text, in the loader's vector font.
 * `oy` is the height and `e` the maximum cell size (it shrinks itself if it does not fit). */
void aae_text(const char *s, int oy, int e);

#endif /* AAE_ROMLOAD_H */
